"use strict";(globalThis.webpackChunkpaper=globalThis.webpackChunkpaper||[]).push([[8797],{2488:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/ai_process","metadata":{"permalink":"/paper/dev/ai_process","source":"@site/dev/ai_process.md","title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","description":"AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\uace0 \uc9c4\ud589\ud558\ub294 \ubc29\ubc95","date":"2026-11-03T00:00:00.000Z","tags":[],"readingTime":0.045,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","description":"AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\uace0 \uc9c4\ud589\ud558\ub294 \ubc29\ubc95","date":"2026-11-03T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","permalink":"/paper/dev/ai_element"}},"content":"# Agent Orchestration\\n\\n# Loop Engineering\\n\\n# Graph Engineering"},{"id":"/ai_element","metadata":{"permalink":"/paper/dev/ai_element","source":"@site/dev/ai_element.md","title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","description":"AI \uc2dc\uc2a4\ud15c\uc744 \uc774\uc6a9\ud558\uae30 \uc704\ud55c \uae30\ubcf8 \uac1c\ub150 Model, Agent, Harness \uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uc544\uc694.","date":"2026-11-02T00:00:00.000Z","tags":[],"readingTime":4.56,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","description":"AI \uc2dc\uc2a4\ud15c\uc744 \uc774\uc6a9\ud558\uae30 \uc704\ud55c \uae30\ubcf8 \uac1c\ub150 Model, Agent, Harness \uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uc544\uc694.","date":"2026-11-02T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"3. AI \uc791\uc5c5 \ud504\ub85c\uc138\uc2a4","permalink":"/paper/dev/ai_process"},"nextItem":{"title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","permalink":"/paper/dev/ai_working"}},"content":"AI\uc5d0\uac8c \uc77c\uc744 \uc2dc\ud0a4\ub294 \ubc29\ubc95, AI\uac00 \uc77c\ud558\ub294 \ud658\uacbd\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95, AI \uac00 \uc791\uc5c5\uc744 \uc5f0\uacb0\ud558\ub294 \ubc29\ubc95 \ub4f1 \uc11c\ub85c\ub2e4\ub978 \uc601\uc5ed\uc744 \uc124\uba85\ud558\uace0 \uc788\uc5b4\uc694.\\n\\n# 1. AI \ubaa8\ub378(AI Model)\\n\\n> \uc0dd\uac01\ud558\uace0 \ud310\ub2e8\ud558\ub294 \ub450\ub1cc\\n\\n\ub300\ub7c9\uc758 \ub370\uc774\ud130\ub97c \ud559\uc2b5\ud574\uc11c \ud328\ud134\uc744 \uc775\ud788\uace0, \uc0c8\ub85c\uc6b4 \uc785\ub825\uc744 \ubc1b\uc558\uc744 \ub54c \uacb0\uacfc\ub97c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \uc2dc\uc2a4\ud15c\uc774\uc5d0\uc694.\\n\ub300\ud45c\uc801\uc73c\ub85c GPT, Claude, Gemini \ubaa8\ub378\uc774 \uc788\uc5b4\uc694.\\n\\n# 2. AI \uc5d0\uc774\uc804\ud2b8(Agent)\\n\\n> \ubaa9\ud45c\ub97c \ubc1b\uace0 \uc2a4\uc2a4\ub85c \uc791\uc5c5\uc744 \uc9c4\ud589\ud558\ub294 \uc77c\uafbc\\n\\n\uc5d0\uc774\uc804\ud2b8\uc758 \ud070 \ud2b9\uc9d5\uc740 \uc2a4\uc2a4\ub85c \ub2e4\uc74c \ud589\ub3d9\uc744 \uacb0\uc815\ud558\uace0, \uc2e4\ud589\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\uc5d0\uc694. \\n\uc77c\ubc18\uc801\uc73c\ub85c AI\uc5d0\uac8c \uad81\uae08\ud55c \uac83\ub4e4\uc744 \ubb3c\uc5b4\ubcf4\uace0 \ub2f5\ubcc0\uc744 \ubc1b\uc796\uc544\uc694. \ubc18\uba74 \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c\ub294 \ubaa9\ud45c\ub97c \uc8fc\uc5b4\uc57c \ud574\uc694. \uadf8\ub7fc \uc5d0\uc774\uc804\ud2b8\ub294 \uadf8 \ubaa9\ud45c\ub97c \ub2ec\uc131\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \uc791\uc5c5\ub4e4\uc744 \uacc4\ud68d\ud558\uace0 \uc2e4\ud589\ud574\uc694.\\n\\n\uc77c\ubc18 \uc801\uc778 AI\uc5d0\uac8c \uc694\uccad\\n\\"\uc774 \ucf54\ub4dc\uc5d0\uc11c \ubb38\uc81c\uac00 \uc788\ub294 \ubd80\ubd84\uc744 \ucc3e\uc544\uc918.\\" -> \ucf54\ub4dc\ub97c \ubd84\uc11d\ud558\uace0 \ubb38\uc81c\uc810\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uadf8\ub7fc \uadf8 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub77c\uace0 \ub610 \uc694\uccad\ud574\uc57c \uaca0\uc8e0.\\n\\n\uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc694\uccad\\n\\"\uc774 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uba54\ubaa8\ub9ac \ub204\uc218 \ubb38\uc81c\ub97c \ucc3e\uc544\uc11c \ud574\uacb0\ud574\uc918\\" -> \ud504\ub85c\uc81d\ud2b8\ub97c \ud0d0\uc0c9\ud558\uace0, \ubd84\uc11d\ud574\uc11c, \ucf54\ub4dc\ub97c \uc218\uc815\ud558\uace0, \uacb0\uacfc\uae4c\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uc5d0 \uc5b4\ub290\ubc94\uc704\uae4c\uc9c0 \uc2e4\ud589\ud560 \uc218 \uc788\ub294\uc9c0 \uad8c\ud55c\uc744 \uc8fc\ub290\ub0d0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc838\uc694.\\n\\n# 3. \ud504\ub86c\ud504\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1(Prompt Engineering)\\n\\n> AI \uc5d0\uac8c \uc6d0\ud558\ub294 \uacb0\uacfc\ub97c \uc5bb\uae30\uc704\ud574 \uc9c8\ubb38\uc774\ub098 \uc9c0\uc2dc\ubb38(Prompt)\uc744 \ud6a8\uacfc\uc801\uc73c\ub85c \uc791\uc131\ud558\ub294 \uae30\uc220\\n\\n\uc608\ub97c \ub4e4\uc5b4 AI\uc5d0\uac8c \ub2e4\uc74c\uacfc \uac19\uc774 \uc694\uccad\ud55c\ub2e4\uace0 \ud574\ubcfc\uac8c\uc694.\\n\\n\uc77c\ubc18\uc801\uc778 \ud504\ub86c\ud504\ud2b8\\n\\"Swift \ucf54\ub4dc\ub97c \ub9ac\ud329\ud1a0\ub9c1\ud574 \uc918.\\"\\n\\n\uad6c\uccb4\uc801\uc778 \ud504\ub86c\ud504\ud2b8\\n\\"\uc774 Swift \ucf54\ub4dc\ub97c \ub9ac\ud329\ud1a0\ub9c1\ud574 \uc918.\\n- \uae30\uc874 \uae30\ub2a5\uc740 \uc720\uc9c0\ud574 \uc918.\\n- \uc911\ubcf5 \ucf54\ub4dc\ub97c \uc81c\uac70\ud574 \uc918.\\n- \uba54\ubaa8\ub9ac \uad00\ub9ac \uce21\uba74\uc5d0\uc11c \ubb38\uc81c\uac00 \uc5c6\ub294\uc9c0 \ud655\uc778\ud574 \uc918.\\n- \ubcc0\uacbd\ud55c \uc774\uc720\ub97c \uc124\uba85\ud574 \uc918.\\"\\n\\n\ub450 \uc694\uccad \ubaa8\ub450 \uac19\uc740 \uc791\uc5c5\uc744 \uc694\uad6c\ud558\uc9c0\ub9cc, \ub450 \ubc88\uc9f8 \uc694\uccad\uc740 \ubaa9\ud45c\uc640 \uc870\uac74\uc774 \ub354 \uba85\ud655\ud574\uc694.\\n\\n\uc774\ucc98\ub7fc \ud504\ub86c\ud504\ud2b8\ub97c \uc5b4\ub5bb\uac8c \uc791\uc131\ud574\uc57c AI\uac00 \uc6d0\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc791\uc5c5\ud560\uc9c0 \uace0\ubbfc\ud558\ub294 \uac83\uc774 \ud504\ub86c\ud504\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\uc774\uc5d0\uc694.\\n\\n# 4. \ucee8\ud14d\uc2a4\ud2b8 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1(Context Engineering)\\n\\n> AI \uc5d0\uac8c \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc798 \uad6c\uc131\ud574\uc11c \uc81c\uacf5\ud558\ub294 \uae30\uc220\\n\\nAI\uac00 \uc791\uc5c5\uc744 \uc81c\ub300\ub85c \uc218\ud589\ud560 \uc218 \uc788\ub3c4\ub85d \ud544\uc694\ud55c \uc815\ubcf4(Context)\ub97c \uc218\uc9d1\ud558\uace0 \uad6c\uc131\ud574\uc11c \uc81c\uacf5\ud558\ub294 \uae30\uc220\uc774\uc5d0\uc694.\\n\\nAI \uc5d0\uac8c \ub9ac\ud329\ud1a0\ub9c1\uc744 \uc694\uccad\ud558\ub354\ub77c\ub3c4 AI\uac00 \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\ub97c \ubaa8\ub974\uba74 \uc801\uc808\ud55c \ucf54\ub4dc\ub97c \uc791\uc131\ud558\uae30 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc5b4\uc694. \uc774\ub54c \uac1c\ubc1c\ud658\uacbd, \uc544\ud0a4\ud14d\ucc98, \ud504\ub85c\uc81d\ud2b8 \uaddc\uce59, \ucc38\uace0 \uc790\ub8cc\ub97c \uac19\uc774 \uc81c\uacf5\ud558\ub294 \uac70\uc608\uc694. \uc774\ub7f0 \uc815\ubcf4\ub97c AI\uac00 \ucc38\uace0\ud560 \uc218 \uc788\ub3c4\ub85d \uad6c\uc131\ud558\uba74, \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc0c1\ud669\uc5d0 \ub9de\ub294 \uacb0\uacfc\ubb3c\uc744 \ub9cc\ub4e4 \uac00\ub2a5\uc131\uc774 \ub192\uc544\uc838\uc694.\\n\\n# 5. \ud558\ub124\uc2a4(Harness)\\n\\n> AI\uac00 \uc81c\ub300\ub85c \uc77c\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uc5b4 \uc8fc\ub294 \uc2e4\ud589 \ud658\uacbd\\n\\nHareness\ub294 \uc6d0\ub798 \uc7a5\ube44\ub97c \uace0\uc815\ud558\ub294 \uc7a5\uce58\ub77c\ub294 \uc758\ubbf8\uac00 \uc788\uc5b4\uc694. AI\ubd84\uc57c\uc5d0\uc11c\ub294 AI \uc5d0\uc774\uc804\ud2b8\uac00 \uc548\uc815\uc801\uc73c\ub85c \uc791\uc5c5\ud560 \uc218 \uc788\ub3c4\ub85d \uc8fc\ubcc0 \ud658\uacbd\uacfc \uaddc\uce59\uc744 \uad6c\uc131\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud574\uc694."},{"id":"/ai_working","metadata":{"permalink":"/paper/dev/ai_working","source":"@site/dev/ai_working.md","title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","description":"AI \uac00 \uc2e4\uc81c\ub85c \uc791\uc5c5\ud558\ub294 \ubc29\ubc95 Skill, Memory, RAG, MCP","date":"2026-11-02T00:00:00.000Z","tags":[],"readingTime":2.925,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"2. AI \uc791\uc5c5 \uc218\ud589 \ubc29\uc2dd","description":"AI \uac00 \uc2e4\uc81c\ub85c \uc791\uc5c5\ud558\ub294 \ubc29\ubc95 Skill, Memory, RAG, MCP","date":"2026-11-02T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"1. AI \uae30\ubcf8 \uad6c\uc131 \uc694\uc18c","permalink":"/paper/dev/ai_element"}},"content":"> \ud2b9\uc815 \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \ubc29\ubc95\uc744 \ubbf8\ub9ac \uc815\uc758\ud55c \uba54\ub274\uc5bc\\n\\n\ub9e4\ubc88 AI\uc5d0\uac8c \uc791\uc5c5 \ubc29\ubc95\uc744 \uc124\uba85\ud558\ub294 \ub300\uc2e0, \ud574\ub2f9 \uc791\uc5c5\uc758 \uaddc\uce59\uacfc \uc808\ucc28\ub97c \uc2a4\ud0ac\ub85c \ub9cc\ub4e4\uc5b4 \ub193\ub294 \uac70\uc608\uc694.\\n\\n\uc608\uc2dc: Swift Code Review Skill\\n\\n\uc774 \uc2a4\ud0ac\uc774 \uc2e4\ud589\ub418\uba74 \ub2e4\uc74c\uc744 \uc218\ud589\ud55c\ub2e4.\\n\\n1. Swift \ucf54\ub4dc\ub97c \ubd84\uc11d\ud55c\ub2e4.\\n2. \uba54\ubaa8\ub9ac \ub204\uc218 \uac00\ub2a5\uc131\uc744 \ud655\uc778\ud55c\ub2e4.\\n3. retain cycle\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4.\\n4. Swift Concurrency \uc0ac\uc6a9\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud55c\ub2e4.\\n5. \uac1c\uc120\ud560 \ubd80\ubd84\uc744 \uc774\uc720\uc640 \ud568\uaed8 \uc81c\uc548\ud55c\ub2e4.\\n\\n\uc774\ud6c4 AI\uc5d0\uac8c \ucf54\ub4dc \ub9ac\ubdf0\ub97c \uc694\uccad\ud558\uba74 \uc2a4\ud0ac\uc5d0 \uc815\uc758\ub41c \ubc29\uc2dd\uc73c\ub85c \uc791\uc5c5\ud574\uc694.\\n\\n# 2. \uba54\ubaa8\ub9ac(Memory)\\n\\n> \uc774\uc804 \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\uace0 \ud65c\uc6a9\ud558\ub294 \uae30\ub2a5\\n\\nAI\uac00 \uc774\uc804\uc5d0 \uc54c\uac8c\ub41c \uc815\ubcf4\ub97c \uc774\ud6c4 \ub300\ud654\ub098 \uc791\uc5c5\uc5d0\uc11c \ud65c\uc6a9\ud558\ub294 \uac1c\ub150\uc774\uc5d0\uc694. Memory \uc5d0\ub294 \uc0ac\uc6a9\uc790 \uc120\ud638 \uc815\ubcf4, \uc9c4\ud589\uc911\uc778 \uc791\uc5c5\uc758 \uc0c1\ud0dc, \uc774\uc804\uc5d0 \uacb0\uc815\ud55c \uc0ac\ud56d, \ubc18\ubcf5\uc801\uc73c\ub85c \ud65c\uc6a9\ud574\uc57c \ud558\ub294 \uc815\ubcf4 \ub4f1\uc774 \uc788\uc5b4\uc694.\\n\\nMemory \uc640 Context \ub294 \uac19\uc740 \uac1c\ub150\uc774 \uc544\ub2c8\uc5d0\uc694.\\n- Memory: \uae30\uc5b5\ud574 \ub450\ub294 \uc815\ubcf4\\n- Context: \ud604\uc7ac \uc791\uc5c5\uc744 \uc218\ud589\ud558\uae30 \uc704\ud574 AI\uc5d0\uac8c \uc81c\uacf5 \ub418\ub294 \uc815\ubcf4\\n\\nMemory\uc5d0 \uc800\uc7a5\ub41c \uc815\ubcf4\uac00 \ub2e4\uc74c \uc791\uc5c5\uc758 Context \ub85c \ud65c\uc6a9 \ub420 \uc218 \uc788\ub294 \uac70\uc608\uc694.\\n\\n# 3. RAG(Retrieval-Augmented Generation)\\n\\n> \uc678\ubd80 \uc790\ub8cc\ub97c \uac80\uc0c9\ud574\uc11c AI\ub2f5\ubcc0\uc5d0 \ud65c\uc6a9\ud558\ub294 \uae30\uc220\\n\\n\uc678\ubd80\uc5d0\uc11c \uad00\ub828 \uc815\ubcf4\ub97c \uac80\uc0c9\ud574 AI\uc5d0\uac8c \uc81c\uacf5\ud558\uace0, \uadf8 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \ub2f5\ubcc0\uc744 \uc0dd\uc131\ud558\ub294 \ubc29\uc2dd\uc774\uc5d0\uc694. RAG\ub294 AI\uac00 \ubb38\uc11c\ub97c \ubbf8\ub9ac \uc804\ubd80 \ud559\uc2b5\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc9c8\ubb38\uc774 \ub4e4\uc5b4\uc654\uc744 \ub54c \ud544\uc694\ud55c \ub0b4\uc6a9\uc744 \ucc3e\uc544\uc11c \ucc38\uace0 \ud574\uc694.\\n\\n# 4. MCP(Model Context Protocol)\\n\\n> AI\uc640 \uc678\ubd80 \ub3c4\uad6c\ub97c \uc5f0\uacb0\ud558\uae30 \uc704\ud55c \uacf5\ud1b5 \ud1b5\uc2e0 \uaddc\uaca9\\n\\nAI\uac00 \uc678\ubd80 \ub3c4\uad6c\ub098 \ub370\uc774\ud130\uc5d0 \uc5f0\uacb0\ud560 \ub54c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud45c\uc900\ud654\ub41c \ud1b5\uc2e0 \uaddc\uaca9\uc774\uc5d0\uc694. \uc608\ub97c\ub4e4\uc5b4 \\"GitHub\uc5d0\uc11c \ud604\uc7ac \uc9c4\ud589\uc911\uc778 Issue \ubaa9\ub85d\uc744 \ud655\uc778\ud574\uc918\\"\ub77c\uace0 \uc694\uccad\ud588\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcfc\uac8c\uc694. \uadf8\ub7f0\ub370 AI \uac00 GitHub\uc5d0 \uc811\uadfc \ud560 \uc218 \uc5c6\ub2e4\uba74 \uc774 \uc791\uc5c5\uc744 \uc9c4\ud589\ud560 \uc218 \uc5c6\uaca0\uc8e0? \uc774\ub54c GitHub MCP Server\uac00 \uc788\ub2e4\uba74 AI\uac00 GitHub \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc5f0\uacb0\ud574 \uc904 \uc218 \uc788\uc5b4\uc694."}]}}')}}]);